oup details...\");\r\n    const getResult = await client.resourceGroups.get(resourceGroupName);\r\n    console.log(\"✓ Resource group details retrieved\");\r\n    console.log(`  Name: ${getResult.name}`);\r\n    console.log(`  Location: ${getResult.location}`);\r\n    console.log(`  ID: ${getResult.id}`);\r\n    console.log(`  Provisioning State: ${getResult.properties?.provisioningState}`);\r\n    console.log(`  Tags:`, JSON.stringify(getResult.tags, null, 2));\r\n    console.log();\r\n\r\n    // Step 6: Update the resource group by adding a tag\r\n    console.log(\"Step 6: Updating resource group with new tag...\");\r\n    const updateResult = await client.resourceGroups.update(\r\n      resourceGroupName,\r\n      {\r\n        tags: {\r\n          ...getResult.tags,\r\n          updatedAt: new Date().toISOString(),\r\n          status: \"modified\",\r\n        },\r\n      }\r\n    );\r\n    console.log(\"✓ Resource group updated successfully\");\r\n    console.log(`  Updated Tags:`, JSON.stringify(updateResult.tags, null, 2));\r\n    console.log();\r\n\r\n    // Step 7: Delete the resource group\r\n    console.log(\"Step 7: Deleting resource group...\");\r\n    console.log(\"  This may take a few minutes...\");\r\n    \r\n    const deletePoller = await client.resourceGroups.beginDelete(\r\n      resourceGroupName\r\n    );\r\n    await deletePoller.pollUntilDone();\r\n    \r\n    console.log(\"✓ Resource group deleted successfully\\n\");\r\n\r\n    // Verify deletion\r\n    console.log(\"Verifying deletion...\");\r\n    try {\r\n      await client.resourceGroups.get(resourceGroupName);\r\n      console.log(\"⚠ Resource group still exists (unexpected)\");\r\n    } catch (error: any) {\r\n      if (error.statusCode === 404) {\r\n        console.log(\"✓ Confirmed: Resource group no longer exists\\n\");\r\n      } else {\r\n        throw error;\r\n      }\r\n    }\r\n\r\n    console.log(\"=\".repeat(60));\r\n    console.log(\"Demo completed successfully!\");\r\n    console.log(\"=\".repeat(60));\r\n\r\n  } catch (error) {\r\n    console.error(\"\\n❌ Error occurred:\");\r\n    if (error instanceof Error) {\r\n      console.error(`  Message: ${error.message}`);\r\n      console.error(`  Stack: ${error.stack}`);\r\n    } else {\r\n      console.error(error);\r\n    }\r\n    process.exit(1);\r\n  }\r\n}\r\n\r\n// Execute the main function\r\nmain();\r\n\n```\n\n### tsconfig.json\n```\n{\r\n  \"compilerOptions\": {\r\n    \"target\": \"ES2020\",\r\n    \"module\": \"commonjs\",\r\n    \"lib\": [\"ES2020\"],\r\n    \"outDir\": \"./dist\",\r\n    \"rootDir\": \"./src\",\r\n    \"strict\": true,\r\n    \"esModuleInterop\": true,\r\n    \"skipLibCheck\": true,\r\n    \"forceConsistentCasingInFileNames\": true,\r\n    \"resolveJsonModule\": true,\r\n    \"moduleResolution\": \"node\"\r\n  },\r\n  \"include\": [\"src/**/*\"],\r\n  \"exclude\": [\"node_modules\"]\r\n}\r\n\n```\n\n### README.md\n```\n# Azure Resource Group Manager\r\n\r\nA TypeScript program demonstrating Azure Resource Group management using the Azure Management Plane SDK (`@azure/arm-resources`).\r\n\r\n## Features\r\n\r\nThis program demonstrates:\r\n1. **Authentication** using `DefaultAzureCredential` from `@azure/identity`\r\n2. **Create** a ResourceManagementClient with credential and subscription ID\r\n3. **Create** a new resource group in the \"eastus\" region\r\n4. **List** all resource groups in the subscription using async iteration\r\n5. **Get** details of the created resource group\r\n6. **Update** the resource group by adding tags\r\n7. **Delete** the resource group using `beginDeleteAndWait` pattern\r\n\r\n## Prerequisites\r\n\r\n- Node.js 18+ and npm\r\n- Azure subscription\r\n- Azure CLI installed and authenticated (`az login`) OR service principal credentials\r\n\r\n## Required Packages\r\n\r\n```json\r\n{\r\n  \"dependencies\": {\r\n    \"@azure/arm-resources\": \"^5.2.0\",\r\n    \"@azure/identity\": \"^4.0.0\"\r\n  },\r\n  \"devDependencies\": {\r\n    